    s = sku.upper()
    m = re.fullmatch(r'AH-?([A-Z]{3})-?(\d{1,4})-?([A-Z]{3})', s)
    return f'AH-{m.group(1)}-{int(m.group(2)):04d}-{m.group(3)}'


def load_products():
    P, V = {}, []
